package com.github.dappermickie.odablock;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.util.Text;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
public abstract class SnowballUserManager
{

	private static final File DOWNLOAD_DIR = new File(RuneLite.RUNELITE_DIR.getPath() + File.separator + "odablock-users");
	private static final HttpUrl RAW_GITHUB = HttpUrl.parse("https://raw.githubusercontent.com/dappermickie/odablock-sounds/snowball");
	private static final String USERVERSION_FILENAME = "USERVERSION";
	private static final String USERS_FILENAME = "users.txt";

	private static volatile String[] users;

	public static void ensureDownloadDirectoryExists()
	{
		if (!DOWNLOAD_DIR.exists())
		{
			DOWNLOAD_DIR.mkdirs();
		}
	}

	public static synchronized void downloadSnowballUsers(final OkHttpClient okHttpClient)
	{
		ensureDownloadDirectoryExists();
		HttpUrl versionUrl = RAW_GITHUB.newBuilder().addPathSegment(USERVERSION_FILENAME).build();
		Path temporary = null;
		try
		{
			int latestVersion;
			try (Response res = okHttpClient.newCall(new Request.Builder().url(versionUrl).build()).execute())
			{
				if (!res.isSuccessful() || res.body() == null)
				{
					return;
				}
				latestVersion = Integer.parseInt(res.body().string().trim());
			}
			int currentVersion = -1;
			try
			{
				currentVersion = getUserVersion();
			}
			catch (IOException | NumberFormatException ignored)
			{
			}
			Path destination = DOWNLOAD_DIR.toPath().resolve(USERS_FILENAME);
			if (latestVersion == currentVersion && Files.isRegularFile(destination))
			{
				return;
			}
			HttpUrl usersUrl = RAW_GITHUB.newBuilder().addPathSegment(USERS_FILENAME).build();
			try (Response res = okHttpClient.newCall(new Request.Builder().url(usersUrl).build()).execute())
			{
				if (!res.isSuccessful() || res.body() == null)
				{
					return;
				}
				temporary = Files.createTempFile(DOWNLOAD_DIR.toPath(), "users-", ".tmp");
				Files.copy(res.body().byteStream(), temporary, StandardCopyOption.REPLACE_EXISTING);
				Files.move(temporary, destination, StandardCopyOption.REPLACE_EXISTING);
				users = null;
				writeLatestVersion(latestVersion);
			}
		}
		catch (IOException | NumberFormatException e)
		{
			log.warn("Odablock Plugin could not update snowball users", e);
		}
		finally
		{
			if (temporary != null)
			{
				try { Files.deleteIfExists(temporary); }
				catch (IOException e) { log.debug("Could not remove temporary user download", e); }
			}
		}
	}

	public static String[] getUsers()
	{
		if (SnowballUserManager.users != null)
		{
			return SnowballUserManager.users;
		}
		File userVersionFile = new File(DOWNLOAD_DIR, USERS_FILENAME);
		try
		{
			String userVersionFileContent = Files.readString(userVersionFile.toPath());
			String[] originalUsers = userVersionFileContent.split(",");
			String[] users = new String[originalUsers.length];

			for (int i = 0; i < originalUsers.length; i++)
			{
				users[i] = Text.standardize(originalUsers[i]);
			}

			SnowballUserManager.users = users;

			return users;
		}
		catch (IOException e)
		{
			return new String[0];
		}
	}

	private static int getUserVersion() throws IOException
	{
		File userVersionFile = new File(DOWNLOAD_DIR, USERVERSION_FILENAME);
		String userVersionFileContent = Files.readString(userVersionFile.toPath());
		return Integer.parseInt(userVersionFileContent.trim());
	}

	private static void writeLatestVersion(int version)
	{
		var soundVersionFile = new File(DOWNLOAD_DIR, USERVERSION_FILENAME);
		try
		{
			FileWriter myWriter = new FileWriter(soundVersionFile);
			myWriter.write(String.valueOf(version));
			myWriter.close();
		}
		catch (IOException e)
		{
			log.error("Couldn't write latest userversion");
		}
	}
}

package com.github.dappermickie.odablock;

import com.github.dappermickie.odablock.overrides.SoundOverrideService;
import com.github.dappermickie.odablock.overrides.SoundPools;
import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.Optional;
import java.util.concurrent.Executor;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.Clip;
import javax.sound.sampled.UnsupportedAudioFileException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Duration;

@Singleton
@Slf4j
public class SoundEngine
{
	@Inject
	private OdablockConfig config;

	@Inject
	private AudioPlayer audioPlayer;

	@Inject
	private SoundOverrideService soundOverrideService;

	private final Object managedClipLock = new Object();
	private Clip managedClip;
	private long managedRequest;
	private volatile boolean active = true;
	private volatile long lifecycle;

	public void playClip(Sound sound, Executor executor)
	{
		long session = lifecycle;
		executor.execute(() -> { if (active && lifecycle == session) playClipInternal(sound); });
	}

	public void playClip(Sound sound, ScheduledExecutorService executor, Duration initialDelay)
	{
		long session = lifecycle;
		executor.schedule(() -> { if (active && lifecycle == session) playClipInternal(sound); }, initialDelay.toMillis(), TimeUnit.MILLISECONDS);
	}

	public void playFile(File file, Executor executor)
	{
		if (file == null)
		{
			return;
		}
		long session = lifecycle;
		executor.execute(() -> { if (active && lifecycle == session) playFileInternal(file); });
	}

	private void playFileInternal(File file)
	{
		if (!active || config.announcementVolume() <= 0 || SoundFileManager.getIsUpdating())
		{
			return;
		}

		float gain = 20f * (float) Math.log10(config.announcementVolume() / 100f);
		try
		{
			audioPlayer.play(file, gain);
		}
		catch (IOException | UnsupportedAudioFileException | LineUnavailableException | IllegalArgumentException exception)
		{
			log.warn("Failed to preview sound {}", file.getName(), exception);
		}
	}

	private void playClipInternal(Sound sound)
	{
		if (!active || config.announcementVolume() <= 0 || SoundFileManager.getIsUpdating())
		{
			return;
		}

		float gain = 20f * (float) Math.log10(config.announcementVolume() / 100f);
		try
		{
			File soundFile = resolveSoundFile(sound).orElse(null);
			if (soundFile == null)
			{
				log.warn("No audio file available for {}", SoundPools.getDisplayName(sound.getDirectory()));
				return;
			}

			audioPlayer.play(soundFile, gain);
		}
		catch (FileNotFoundException e)
		{
			log.warn("Sound file not found for " + sound, e);
		}
		catch (IOException e)
		{
			log.warn("Failed to play Odablock sound " + sound, e);
		}
		catch (UnsupportedAudioFileException e)
		{
			log.warn("Failed to play Odablock sound " + sound, e);
		}
		catch (LineUnavailableException | IllegalArgumentException e)
		{
			log.warn("Failed to play Odablock sound " + sound, e);
		}
	}

	public void playManagedClip(Sound sound, Executor executor)
	{
		final long request;
		synchronized (managedClipLock)
		{
			request = ++managedRequest;
		}
		executor.execute(() -> playManagedClipInternal(sound, request));
	}

	public void stopManagedClip()
	{
		Clip previous;
		synchronized (managedClipLock)
		{
			++managedRequest;
			previous = managedClip;
			managedClip = null;
		}
		closeClip(previous);
	}

	private static void closeClip(Clip clip)
	{
		if (clip != null)
		{
			clip.stop();
			clip.close();
		}
	}

	private void playManagedClipInternal(Sound sound, long request)
	{
		synchronized (managedClipLock)
		{
			if (request != managedRequest || !active || config.announcementVolume() <= 0
				|| SoundFileManager.getIsUpdating())
			{
				return;
			}
		}

		Clip clip = null;
		boolean published = false;
		try
		{
			File soundFile = resolveSoundFile(sound).orElse(null);
			if (soundFile == null)
			{
				log.warn("No audio file available for {}", SoundPools.getDisplayName(sound.getDirectory()));
				return;
			}

			try (AudioInputStream stream = AudioSystem.getAudioInputStream(soundFile))
			{
				clip = AudioSystem.getClip();
				clip.open(stream);
			}
			try
			{
				var control = (javax.sound.sampled.FloatControl) clip.getControl(javax.sound.sampled.FloatControl.Type.MASTER_GAIN);
				float gain = 20f * (float) Math.log10(config.announcementVolume() / 100f);
				control.setValue(Math.max(control.getMinimum(), Math.min(control.getMaximum(), gain)));
			}
			catch (IllegalArgumentException e)
			{
				log.debug("Managed clip gain is not supported", e);
			}

			final Clip openedClip = clip;
			clip.addLineListener(event -> {
				if (event.getType() == javax.sound.sampled.LineEvent.Type.STOP)
				{
					synchronized (managedClipLock)
					{
						if (managedClip == openedClip)
						{
							managedClip = null;
						}
					}
					openedClip.close();
				}
			});

			Clip previous;
			synchronized (managedClipLock)
			{
				// A stop, newer selection, or shutdown may arrive while audio is decoding.
				if (!active || request != managedRequest || config.announcementVolume() <= 0)
				{
					return;
				}
				previous = managedClip;
				managedClip = clip;
				clip.start();
				published = true;
			}
			closeClip(previous);
		}
		catch (IOException | UnsupportedAudioFileException | LineUnavailableException | IllegalArgumentException e)
		{
			log.warn("Failed to play managed Odablock sound {}", sound, e);
		}
		finally
		{
			if (!published && clip != null)
			{
				synchronized (managedClipLock)
				{
					if (managedClip == clip) managedClip = null;
				}
				clip.close();
			}
		}
	}

	private Optional<File> resolveSoundFile(Sound sound) throws FileNotFoundException
	{
		String poolDirectory = sound.getDirectory();
		File soundFile = soundOverrideService.getRandomOverrideFile(poolDirectory).orElseGet(() -> {
			try
			{
				return SoundFileManager.getSoundStream(sound);
			}
			catch (FileNotFoundException fileNotFoundException)
			{
				return null;
			}
		});

		return Optional.ofNullable(soundFile);
	}

	public void startUp()
	{
		active = true;
	}

	public void close()
	{
		active = false;
		lifecycle++;
		stopManagedClip();
	}
}

