package com.github.dappermickie.odablock.emotes;

import com.google.common.collect.ImmutableMap;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.client.util.ImageUtil;

public class Emote
{
	@Getter private String trigger;
	@Getter private String[] altTriggers = new String[0];
	private String file;
	private String overheadFile;
	private transient BufferedImage image;
	private transient BufferedImage overheadImage;
	private transient int index;
	private static Emote[] current = new Emote[0];
	private static Map<String, Emote> emojiMap = new java.util.HashMap<>();

	static Emote[] values() { return current; }
	int ordinal() { return index; }
	BufferedImage loadImage() { return image; }
	BufferedImage loadOverheadImage() { return overheadImage; }
	void prepare(java.nio.file.Path directory) throws java.io.IOException
	{
		image = read(directory, file);
		overheadImage = overheadFile == null ? image : read(directory, overheadFile);
	}
	private BufferedImage read(java.nio.file.Path directory, String name) throws java.io.IOException
	{
		BufferedImage result = javax.imageio.ImageIO.read(directory.resolve(name).toFile());
		if (result == null) throw new java.io.IOException("Invalid emote image: " + name);
		return toChatIconImage(result);
	}
	String[] files() { return overheadFile == null ? new String[]{file} : new String[]{file, overheadFile}; }
	static void install(Emote[] emotes)
	{
		Map<String, Emote> mapping = new java.util.HashMap<>();
		for (int i = 0; i < emotes.length; i++)
		{
			Emote emote = emotes[i];
			emote.index = i;
			java.util.List<String> triggers = new java.util.ArrayList<>(java.util.Arrays.asList(emote.altTriggers));
			triggers.add(emote.trigger);
			for (String trigger : triggers)
			{
				trigger = trigger.toLowerCase(java.util.Locale.ROOT);
				mapping.put(trigger, emote);
				if (!trigger.startsWith("oda") && !trigger.startsWith(":")) mapping.put("oda" + trigger, emote);
			}
		}
		current = emotes;
		emojiMap = mapping;
	}

	static BufferedImage toChatIconImage(BufferedImage image)
	{
		int width = image.getWidth();
		int height = image.getHeight();
		int[] pixels = image.getRGB(0, 0, width, height, null, 0, width);
		Set<Integer> colors = new HashSet<>();
		for (int pixel : pixels)
		{
			// RuneLite only draws fully opaque pixels in indexed chat sprites.
			if ((pixel >>> 24) == 255)
			{
				colors.add(pixel & 0xFFFFFF);
			}
		}
		if (colors.size() <= 255)
		{
			return image;
		}

		// Six levels per channel give at most 216 colors, leaving room for transparency.
		for (int i = 0; i < pixels.length; i++)
		{
			int pixel = pixels[i];
			if ((pixel >>> 24) != 255)
			{
				continue;
			}
			int red = (((pixel >>> 16) & 255) + 25) / 51 * 51;
			int green = (((pixel >>> 8) & 255) + 25) / 51 * 51;
			int blue = ((pixel & 255) + 25) / 51 * 51;
			int rgb = (red << 16) | (green << 8) | blue;
			// RuneLite reserves RGB zero for transparency; keep dark pixels visible.
			pixels[i] = 0xFF000000 | (rgb == 0 ? 1 : rgb);
		}
		BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		result.setRGB(0, 0, width, height, pixels, 0, width);
		return result;
	}

	static Emote getEmoji(String trigger)
	{
		return emojiMap.get(trigger);
	}
}

package com.github.dappermickie.odablock.emotes;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.RuneLite;
import okhttp3.*;

@Singleton
public class EmoteCatalog
{
 private static final String BASE = "https://raw.githubusercontent.com/DapperMickie/odablock-sounds/emotes/";
 private static final Path CACHE = RuneLite.RUNELITE_DIR.toPath().resolve("odablock-emotes");
 @Inject private OkHttpClient http;
 @Inject private Gson gson;
 private static class Manifest { int version; Emote[] emotes; }
 private String installed;
 synchronized void reset() { installed = null; }

 synchronized Emote[] refresh() throws IOException
 {
  Files.createDirectories(CACHE);
  String json;
  try { json = new String(download("emotes.json"), StandardCharsets.UTF_8); }
  catch (IOException failure)
  {
   if (!Files.exists(CACHE.resolve("emotes.json"))) throw failure;
   json = Files.readString(CACHE.resolve("emotes.json"));
  }
  if (json.equals(installed)) return null;
  Manifest manifest = gson.fromJson(json, Manifest.class);
  if (manifest == null || manifest.version < 1 || manifest.emotes == null || manifest.emotes.length == 0)
   throw new IOException("Invalid emote manifest");
  Path directory = CACHE.resolve(Integer.toString(manifest.version));
  Files.createDirectories(directory);
  for (Emote emote : manifest.emotes)
  {
   if (emote == null || emote.getTrigger() == null || emote.getTrigger().isEmpty() || emote.getAltTriggers() == null)
    throw new IOException("Invalid emote trigger");
   for (String file : emote.files())
   {
    if (file == null || !file.matches("[a-zA-Z0-9_-]+\\.png")) throw new IOException("Invalid emote filename");
    Path target = directory.resolve(file);
    if (!Files.exists(target))
    {
     byte[] bytes = download(file);
     if (javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes)) == null) throw new IOException("Invalid image");
     Path temporary = Files.createTempFile(directory, "emote", ".tmp");
     try { Files.write(temporary, bytes); Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING); }
     finally { Files.deleteIfExists(temporary); }
    }
   }
   emote.prepare(directory);
  }
  Files.writeString(CACHE.resolve("emotes.json"), json);
  installed = json;
  return manifest.emotes;
 }
 private byte[] download(String file) throws IOException
 {
  try (Response response = http.newCall(new Request.Builder().url(BASE + file).build()).execute())
  {
   if (!response.isSuccessful() || response.body() == null) throw new IOException("Emote download failed: " + file);
   return response.body().bytes();
  }
 }
}

package com.github.dappermickie.odablock.emotes;

import com.github.dappermickie.odablock.OdablockConfig;
import static com.github.dappermickie.odablock.OdablockPlugin.ODABLOCK;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import joptsimple.internal.Strings;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class EmoteHandler
{
	private static final Pattern WHITESPACE_REGEXP = Pattern.compile("[\\s\\u00A0]");

	@Inject
	private ChatIconManager chatIconManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Client client;

	@Inject
	private OdablockConfig config;

	private int[] chatIconIds;
	private int[] overheadIconIds;

	@Inject private EmoteCatalog catalog;
	@Inject private java.util.concurrent.ScheduledExecutorService executor;
	private java.util.concurrent.Future<?> refreshTask;
	private long generation;

	public void loadEmotes()
	{
		catalog.reset();
		long active = ++generation;
		refreshTask = executor.submit(() -> {
			try
			{
				Emote[] emotes = catalog.refresh();
				if (emotes != null) clientThread.invoke(() -> {
					if (generation != active) return;
					install(emotes);
				});
			}
			catch (Exception e) { log.warn("Could not refresh emotes", e); }
		});
	}
	public void shutDown()
	{
		++generation;
		if (refreshTask != null) refreshTask.cancel(false);
	}
	private void install(Emote[] emotes)
	{
		final int[] loadedChatIconIds = new int[emotes.length];
		final int[] loadedOverheadIconIds = new int[emotes.length];

		for (int i = 0; i < emotes.length; i++)
		{
			final Emote emoji = emotes[i];
			final BufferedImage chatImage = emoji.loadImage();
			final BufferedImage overheadImage = emoji.loadOverheadImage();
			loadedChatIconIds[i] = chatIconManager.registerChatIcon(chatImage);
			loadedOverheadIconIds[i] = chatIconManager.registerChatIcon(overheadImage);
		}
		overheadIconIds = loadedOverheadIconIds;
		chatIconIds = loadedChatIconIds;
		Emote.install(emotes);
	}

	public void onChatMessage(ChatMessage chatMessage)
	{
		if (!config.emotes())
		{
			return;
		}

		if (chatIconIds == null)
		{
			return;
		}

		switch (chatMessage.getType())
		{
			case PUBLICCHAT:
			case MODCHAT:
			case FRIENDSCHAT:
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
			case PRIVATECHAT:
			case PRIVATECHATOUT:
			case MODPRIVATECHAT:
				break;
			default:
				return;
		}

		final MessageNode messageNode = chatMessage.getMessageNode();
		final String message = messageNode.getValue();
		final String updatedMessage = updateMessage(message, false);

		if (updatedMessage == null)
		{
			return;
		}

		messageNode.setValue(updatedMessage);
	}

	public void onOverheadTextChanged(final OverheadTextChanged event)
	{
		if (!config.emotes())
		{
			return;
		}

		if (!(event.getActor() instanceof Player))
		{
			return;
		}

		final String message = event.getOverheadText();
		final String updatedMessage = updateMessage(message, true);

		if (updatedMessage == null)
		{
			return;
		}

		event.getActor().setOverheadText(updatedMessage);
	}

	public void onCommandExecuted(CommandExecuted event)
	{
		if (event.getCommand().startsWith("odaemote") || event.getCommand().startsWith("odablockemote"))
		{
			clientThread.invoke(this::sendOdaEmotes);
		}
	}

	private void sendOdaEmotes()
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, ODABLOCK, "Odablock emote list:", null);
		for (Emote emote : Emote.values())
		{
			final int emoteId = chatIconIds[emote.ordinal()];
			final String emoteImage = "<img=" + chatIconManager.chatIconIndex(emoteId) + ">";
			StringBuilder chatMessageSb = new StringBuilder();
			chatMessageSb.append(emote.getTrigger());
			chatMessageSb.append(" : ");
			chatMessageSb.append(emoteImage);
			List<String> altTriggerOriginal = Arrays.asList(emote.getAltTriggers());
			List<String> altTriggers = new ArrayList<>(altTriggerOriginal);
			if (!emote.getTrigger().startsWith("oda") && !emote.getTrigger().startsWith(":"))
			{
				altTriggers.add("oda" + emote.getTrigger());
			}
			for (int i = 0; i < altTriggers.size(); i++)
			{
				if (i == 0)
				{
					chatMessageSb.append(" (alt: ");
				}
				else
				{
					chatMessageSb.append(", ");
				}
				String altTrigger = altTriggers.get(i);
				chatMessageSb.append(altTrigger);
				if (!altTrigger.startsWith("oda") && !altTrigger.startsWith(":"))
				{
					chatMessageSb.append(", oda");
					chatMessageSb.append(altTrigger);
				}
				if (i == (altTriggers.size() - 1))
				{
					chatMessageSb.append(" )");
				}
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, ODABLOCK, chatMessageSb.toString(), null);
		}
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, ODABLOCK, "Some emotes have an alternative trigger that will get translated into an emote.", null);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, ODABLOCK, "For example: both \"cap\" and \"odacap\" work.", null);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, ODABLOCK, "To disable an emote, you can add it to the \"Emote Ignore List\" in the plugin settings.", null);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, ODABLOCK, "Add the emote and the alternative triggers to completely disable an emote.", null);
	}

	@Nullable
	String updateMessage(final String message, final boolean isOverhead)
	{
		if (chatIconIds == null || message == null)
		{
			return null;
		}

		final String[] messageWords = WHITESPACE_REGEXP.split(message);
		final String[] ignoredEmotes = config.emoteIgnoreList().split(",");

		boolean editedMessage = false;
		for (int i = 0; i < messageWords.length; i++)
		{
			// Remove tags except for <lt> and <gt>
			final String originalTrigger = Text.removeFormattingTags(messageWords[i]);
			final String trigger = originalTrigger.toLowerCase(Locale.ROOT);
			final Emote emote = Emote.getEmoji(trigger);

			if (emote == null)
			{
				continue;
			}

			boolean shouldSkip = false;
			for (String ignored : ignoredEmotes)
			{
				if (ignored.strip().equalsIgnoreCase(trigger))
				{
					shouldSkip = true;
					break;
				}
			}

			if (shouldSkip)
			{
				continue;
			}

			final int emoteId = isOverhead ? overheadIconIds[emote.ordinal()] : chatIconIds[emote.ordinal()];
			messageWords[i] = messageWords[i].replace(originalTrigger, "<img=" + chatIconManager.chatIconIndex(emoteId) + ">");
			editedMessage = true;
		}

		// If we haven't edited the message any, don't update it.
		if (!editedMessage)
		{
			return null;
		}

		return Strings.join(messageWords, " ");
	}
}

