import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;
import java.util.regex.Pattern;

import static com.github.dappermickie.odablock.OdablockPlugin.ODABLOCK;

@Singleton
@Slf4j
public class KillingPlayer
{

	@Inject
	private Client client;

	@Inject
	private OdablockConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ScheduledExecutorService executor;

	private final String message = "Good shit ma brotha don't forget your key!";

	private int lmsKills = 0;

	public boolean onChatMessage(ChatMessage chatMessage)
	{
		Player local = client.getLocalPlayer();
		String standardized = Text.standardize(chatMessage.getMessage());
		// Player Kill message checks
		if (config.playerKilling() &&
			"".equals(chatMessage.getName()))
		{
			if (standardized.contains("%"))
			{
				return false;
			}
			Pattern[] patterns = PlayerKillLineManager.getPatterns();
			if (isPlayerKillMessage(standardized, patterns))
			{
				playSound(true);
				return true;
			}

			if (local != null && standardized.equalsIgnoreCase(local.getName() + " has won!"))
			{
				playSound(false);
				return true;
			}
		}
		return false;
	}

	static boolean isPlayerKillMessage(String message, Pattern[] patterns)
	{
		// Loot broadcasts can start with a player's name, including names such as "Rip Arthur"
		// that match the intentionally broad "rip.*" PvP kill pattern.
		if (message.contains(" received a drop:"))
		{
			return false;
		}

		for (Pattern pattern : patterns == null ? new Pattern[0] : patterns)
		{
			if (pattern != null && pattern.matcher(message).matches())
			{
				return true;
			}
		}

		return false;
	}

	public void onVarbitChanged(VarbitChanged event)
	{
		final int id = event.getVarbitId();
		final int val = event.getValue();
		final int varpId = event.getVarpId();

		if (id == 5315 && varpId == 1377 && val != lmsKills)
		{
			lmsKills = val;

			if (lmsKills > 0 && config.playerKilling())
			{
				playSound(true);
			}
		}
	}

	private void playSound(boolean sendMessage)
	{
		if (config.showChatMessages() && sendMessage)
		{
			client.addChatMessage(ChatMessageType.PUBLICCHAT, ODABLOCK, message, null);
		}
		soundEngine.playClip(Sound.KILLING_SOMEONE_1, executor);
	}
}

package com.github.dappermickie.odablock.sounds;

import com.github.dappermickie.odablock.OdablockConfig;
import com.github.dappermickie.odablock.Sound;
import com.github.dappermickie.odablock.SoundEngine;
import java.util.Random;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.annotations.Varbit;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.game.NpcUtil;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
@Slf4j
public class KillingRat extends TimedSoundBase
{

	@Inject
	private Client client;

	@Inject
	private OdablockConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private NpcUtil npcUtil;

	private NPC currentlyInteractingWithRat;
	private int lastInteractedWithRatTick = -1;

	private static final Pattern KILLCOUNT_PATTERN = Pattern.compile("Your Scurrius kill count is:.*");

	private String[] ratNames = new String[]{
		"rat",
		"giant rat",
		"scurrius",
		"zombie rat",
		"brine rat",
		"hell-rat behemoth",
		"dungeon rat",
		"crypt rat",
		"giant crypt rat",
		"giant rat (scurrius)" // ?
	};

	KillingRat()
	{
		super(10);
	}

	public boolean onChatMessage(ChatMessage chatMessage)
	{
		if (!config.killingRat())
		{
			return false;
		}

		if (!"".equals(chatMessage.getName()))
		{
			return false;
		}

		int currentTick = client.getTickCount();
		if (!canPlaySound(currentTick))
		{
			return false;
		}

		if (!KILLCOUNT_PATTERN.matcher(chatMessage.getMessage()).matches())
		{
			return false;
		}

		setLastPlayedTickTick(currentTick);
		soundEngine.playClip(Sound.KILLING_RAT_OR_SCURRIUS_1, executor);
		return true;
	}

	public void onNpcDespawned(NpcDespawned npcDespawned)
	{
		if (!config.killingRat())
		{
			return;
		}
		int currentTick = client.getTickCount();
		if (!canPlaySound(currentTick))
		{
			return;
		}

		NPC npc = npcDespawned.getNpc();

		if (npc != currentlyInteractingWithRat)
		{
			return;
		}

		if (!npcUtil.isDying(npc))
		{
			return;
		}

		if (!isNpcRat(npc))
		{
			return;
		}

		if (currentTick - lastInteractedWithRatTick > 10)
		{
			// Someone else probably killed it
			return;
		}

		setLastPlayedTickTick(currentTick);
		soundEngine.playClip(Sound.KILLING_RAT_OR_SCURRIUS_1, executor);
	}


	public void onInteractingChanged(InteractingChanged event)
	{
		// Check if we don't have a player, return
		if (!(event.getSource() instanceof Player) && !(event.getTarget() instanceof Player))
		{
			return;
		}

		Player player;
		NPC npc;

		// Check if source is player
		if (event.getSource() instanceof Player)
		{
			// Check if target is npc, if not return
			if (!(event.getTarget() instanceof NPC))
			{
				return;
			}
			player = (Player) event.getSource();
			npc = (NPC) event.getTarget();
		}
		else
		{
			// Check if source is npc, if not return
			if (!(event.getSource() instanceof NPC))
			{
				return;
			}
			player = (Player) event.getTarget();
			npc = (NPC) event.getSource();
		}

		Player localPlayer = client.getLocalPlayer();
		// We must be interacting with the npc
		if (player != localPlayer)
		{
			return;
		}

		// Check if npc is rat
		if (!isNpcRat(npc))
		{
			return;
		}
		lastInteractedWithRatTick = client.getTickCount();
		currentlyInteractingWithRat = npc;
	}

	private boolean isNpcRat(NPC npc)
	{
		String name = Text.standardize(npc.getName());
		for (String ratName : ratNames)
		{
			if (ratName.equals(name))
			{
				return true;
			}
		}

		return false;
	}
}

package com.github.dappermickie.odablock.sounds;

import com.github.dappermickie.odablock.OdablockConfig;
import com.github.dappermickie.odablock.Sound;
import com.github.dappermickie.odablock.SoundEngine;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;

import static com.github.dappermickie.odablock.OdablockPlugin.ODABLOCK;

@Singleton
@Slf4j
public class LevelUp
{
	@Inject
	private Client client;

	@Inject
	private OdablockConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ScheduledExecutorService executor;

	private static final int MAX_TOTAL_LEVEL = 2376;

	private static final String message = "Level up: completed.";
	private static final String level99Message = "Level 99: completed.";
	private static final String maxTotalLevelMessage = "Max total level: completed.";
	private static final int LOGIN_STAT_SYNC_TICK_GRACE = 1;
	private static final int PVP_ARENA_WORLD_1 = 558;
	private static final int PVP_ARENA_WORLD_2 = 570;
	private static final int PVP_ARENA_WORLD_3 = 578;

	private final Map<Skill, Integer> oldExperience = new EnumMap<>(Skill.class);
	private int oldTotalLevel = -1;
	private int lastLoginTick = -1;

	public void onStatChanged(StatChanged statChanged)
	{
		final Skill skill = statChanged.getSkill();

		// Modified from Nightfirecat's virtual level ups plugin as this info isn't (yet?) built in to statChanged event
		final int xpAfter = client.getSkillExperience(skill);
		final int levelAfter = Experience.getLevelForXp(xpAfter);
		final int xpBefore = oldExperience.getOrDefault(skill, -1);
		final int levelBefore = xpBefore == -1 ? -1 : Experience.getLevelForXp(xpBefore);
		final int totalLevelBefore = oldTotalLevel;
		final int totalLevelAfter = client.getTotalLevel();

		oldExperience.put(skill, xpAfter);
		oldTotalLevel = totalLevelAfter;

		if (isPvpArenaWorld())
		{
			return;
		}

		// Ignore the login stat sync window. During this period, the client can report
		// transient stat values that would otherwise look like massive level jumps.
		if (lastLoginTick >= 0 && client.getTickCount() <= lastLoginTick + LOGIN_STAT_SYNC_TICK_GRACE)
		{
			return;
		}

		// Do not proceed if any of the following are true:
		//  * xpBefore == -1              (don't fire when first setting new known value)
		//  * xpAfter <= xpBefore         (do not allow 200m -> 200m exp drops)
		//  * levelBefore >= levelAfter   (stop if if we're not actually reaching a new level)
		//  * levelAfter > MAX_REAL_LEVEL && config says don't include virtual (level is virtual and config ignores virtual)
		if (xpBefore == -1 || xpAfter <= xpBefore || levelBefore >= levelAfter ||
			(levelAfter > Experience.MAX_REAL_LEVEL && !config.announceLevelUpIncludesVirtual()))
		{
			return;
		}

		// Hitting level 99 in a skill is a milestone and gets its own sound/announcement,
		// taking precedence over the generic level-up sound for that single event.
		final boolean justReached99 = levelBefore < Experience.MAX_REAL_LEVEL
			&& levelAfter >= Experience.MAX_REAL_LEVEL;

		final boolean justMaxed = totalLevelBefore >= 0
			&& totalLevelBefore < MAX_TOTAL_LEVEL && totalLevelAfter >= MAX_TOTAL_LEVEL;
		final boolean announceMaxTotalLevel = justReached99 && justMaxed && config.announceMaxTotalLevel();
		if (justReached99 && (config.announceLevel99() || announceMaxTotalLevel))
		{

			if (config.showChatMessages())
			{
				client.addChatMessage(
					ChatMessageType.PUBLICCHAT,
					ODABLOCK,
					announceMaxTotalLevel ? maxTotalLevelMessage : level99Message,
					null
				);
			}

			if (announceMaxTotalLevel)
			{
				soundEngine.playClip(Sound.BIG_GAMON, executor);
			}
			else
			{
				soundEngine.playClip(Sound.REGULAR_GAMON, executor);
			}
			return;
		}

		if (config.announceLevelUp())
		{
			if (config.showChatMessages())
			{
				client.addChatMessage(ChatMessageType.PUBLICCHAT, ODABLOCK, message, null);
			}
			soundEngine.playClip(Sound.LEVEL_UP, executor);
		}
	}

	public void clear()
	{
		oldExperience.clear();
		oldTotalLevel = -1;
		lastLoginTick = -1;
	}

	public void setOldExperience()
	{
		for (final Skill skill : Skill.values())
		{
			oldExperience.put(skill, client.getSkillExperience(skill));
		}
		oldTotalLevel = client.getTotalLevel();
	}

	public void setLastLoginTick(int tick)
	{
		lastLoginTick = tick;
	}

	private boolean isPvpArenaWorld()
	{
		final int world = client.getWorld();
		return world == PVP_ARENA_WORLD_1 || world == PVP_ARENA_WORLD_2 || world == PVP_ARENA_WORLD_3;
	}
}

