package com.github.dappermickie.odablock.sounds;

import com.github.dappermickie.odablock.OdablockConfig;
import com.github.dappermickie.odablock.Sound;
import com.github.dappermickie.odablock.SoundEngine;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.NpcID;

@Singleton
@Slf4j
public class RandomEventSpawned
{
	private static final int INTERACTION_CHECK_DELAY_TICKS = 3;

	@Inject
	private Client client;

	@Inject
	private OdablockConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ScheduledExecutorService executor;

	private static final Set<Integer> RANDOM_EVENT_NPC_IDS = Set.of(
		NpcID.MACRO_BEEKEEPER_INVITATION,
		NpcID.MACRO_COMBILOCK_PIRATE,
		NpcID.MACRO_JEKYLL,
		NpcID.MACRO_JEKYLL_UNDERWATER,
		NpcID.MACRO_DWARF,
		NpcID.PATTERN_INVITATION,
		NpcID.MACRO_EVIL_BOB_OUTSIDE,
		NpcID.MACRO_EVIL_BOB_PRISON,
		NpcID.PINBALL_INVITATION,
		NpcID.MACRO_FORESTER_INVITATION,
		NpcID.MACRO_FROG_CRIER,
		NpcID.MACRO_GENI,
		NpcID.MACRO_GENI_UNDERWATER,
		NpcID.MACRO_GILES,
		NpcID.MACRO_GILES_UNDERWATER,
		NpcID.MACRO_GRAVEDIGGER_INVITATION,
		NpcID.MACRO_MILES,
		NpcID.MACRO_MILES_UNDERWATER,
		NpcID.MACRO_MYSTERIOUS_OLD_MAN,
		NpcID.MACRO_MYSTERIOUS_OLD_MAN_UNDERWATER,
		NpcID.MACRO_MAZE_INVITATION,
		NpcID.MACRO_MIME_INVITATION,
		NpcID.MACRO_NILES,
		NpcID.MACRO_NILES_UNDERWATER,
		NpcID.MACRO_PILLORY_GUARD,
		NpcID.GRAB_POSTMAN,
		NpcID.MACRO_MAGNESON_INVITATION,
		NpcID.MACRO_HIGHWAYMAN,
		NpcID.MACRO_HIGHWAYMAN_UNDERWATER,
		NpcID.MACRO_SANDWICH_LADY_NPC,
		NpcID.MACRO_DRILLDEMON_INVITATION,
		NpcID.MACRO_COUNTCHECK_SURFACE,
		NpcID.MACRO_COUNTCHECK_UNDERWATER
	);
	private final List<PendingRandomEventCheck> pendingChecks = new ArrayList<>();

	public void onNpcSpawned(NpcSpawned npcSpawned)
	{
		if (!config.randomEventSpawned() || npcSpawned.getNpc() == null)
		{
			return;
		}

		final NPC npc = npcSpawned.getNpc();
		final int npcId = npc.getId();
		if (!isRandomEventNpcId(npcId))
		{
			return;
		}

		final int dueTick = client.getTickCount() + INTERACTION_CHECK_DELAY_TICKS;
		pendingChecks.add(new PendingRandomEventCheck(npc, npcId, dueTick));
	}

	public void onGameTick(final GameTick gameTick)
	{
		if (pendingChecks.isEmpty())
		{
			return;
		}

		if (!config.randomEventSpawned())
		{
			pendingChecks.clear();
			return;
		}

		final int currentTick = client.getTickCount();
		final Iterator<PendingRandomEventCheck> iterator = pendingChecks.iterator();
		while (iterator.hasNext())
		{
			final PendingRandomEventCheck check = iterator.next();
			if (currentTick >= check.dueTick)
			{
				verifyInteractionAndPlaySound(check.npc, check.npcId);
				iterator.remove();
			}
		}
	}

	public boolean isRandomEventNpcId(final int npcId)
	{
		return RANDOM_EVENT_NPC_IDS.contains(npcId);
	}

	private void verifyInteractionAndPlaySound(final NPC npc, final int npcId)
	{
		final Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || npc.getInteracting() != localPlayer)
		{
			log.debug("Random event NPC did not target local player after delay: {} (name='{}')",
				npcId, npc.getName());
			return;
		}

		log.debug("Random event NPC spawned for local player: {} (name='{}', interactingLocal={})",
			npcId, npc.getName(), npc.getInteracting() == localPlayer);
		soundEngine.playClip(Sound.GETTING_RAGGED, executor);
	}

	private static class PendingRandomEventCheck
	{
		private final NPC npc;
		private final int npcId;
		private final int dueTick;

		private PendingRandomEventCheck(final NPC npc, final int npcId, final int dueTick)
		{
			this.npc = npc;
			this.npcId = npcId;
			this.dueTick = dueTick;
		}
	}
}

package com.github.dappermickie.odablock.sounds;

import com.github.dappermickie.odablock.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.SoundEffectPlayed;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;

import static com.github.dappermickie.odablock.OdablockPlugin.ODABLOCK;

@Singleton
@Slf4j
public class RedemptionProc extends TimedSoundBase
{

	private boolean redemptionHasProcced = false;

	@Inject
	private Client client;

	@Inject
	private OdablockConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ScheduledExecutorService executor;

	RedemptionProc()
	{
		super(5);
	}

	public void onTick(int currentTick, Player local)
	{
		if (config.redemptionMessage() && !redemptionHasProcced)
		{

			boolean procced = local.hasSpotAnim(AnimationIds.REDEMPTION_PROC.Id);
			if (procced)
			{
				if (canPlaySound(currentTick))
				{
					redemptionHasProcced = true;
					setLastPlayedTickTick(currentTick);
					if (config.showChatMessages())
					{
						//TODO: Add different chat message
						client.addChatMessage(ChatMessageType.PUBLICCHAT, ODABLOCK, "Your redemption has procced.", null);
					}
					soundEngine.playClip(Sound.REDEMPTION_PROC, executor);
					return;
				}
			}
		}
	}

	@Override
	public void cleanupTicks(int currentTick)
	{
		int lastRedemptionProcTick = getLastPlayedTick();
		if (redemptionHasProcced &&
			lastRedemptionProcTick != currentTick &&
			(currentTick < lastRedemptionProcTick || currentTick - lastRedemptionProcTick > getTickDelay()))
		{
			setLastPlayedTickTick(-1);
			redemptionHasProcced = false;
		}
	}

	public void onSoundPlayed(SoundEffectPlayed event)
	{
		Player local = client.getLocalPlayer();
		int soundId = event.getSoundId();

		if (config.redemptionMessage())
		{
			if (local == event.getSource())
			{
				if (soundId == SoundIds.REDEMPTION_PROC.Id)
				{
					event.consume();
					return;
				}
			}
		}
	}

	public boolean HasRedemptionProcced()
	{
		return redemptionHasProcced;
	}
}

package com.github.dappermickie.odablock.sounds;

import com.github.dappermickie.odablock.OdablockConfig;
import com.github.dappermickie.odablock.Sound;
import com.github.dappermickie.odablock.SoundEngine;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;

@Singleton
@Slf4j
public class ReportPlayer
{

	@Inject
	private Client client;

	@Inject
	private OdablockConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ScheduledExecutorService executor;

	private static final String REPORT_FOR = "Report for";
	private static final String REPORT_CONFIRMATION = "Thank you for submitting your abuse report";
	private static final int DUPLICATE_WINDOW_TICKS = 2;

	private int lastPlaybackTick = Integer.MIN_VALUE;

	public void onMenuOptionClicked(MenuOptionClicked menuOptionClicked)
	{
		if (config.sendReport() && isReportOption(menuOptionClicked.getMenuOption()))
		{
			playSoundOnce();
		}
	}

	public void onChatMessage(ChatMessage chatMessage)
	{
		if (config.sendReport()
			&& chatMessage.getType() == ChatMessageType.GAMEMESSAGE
			&& isReportConfirmation(chatMessage.getMessage()))
		{
			playSoundOnce();
		}
	}

	static boolean isReportOption(String option)
	{
		return option != null && REPORT_FOR.equalsIgnoreCase(Text.removeTags(option).trim());
	}

	static boolean isReportConfirmation(String message)
	{
		return message != null && Text.removeTags(message).contains(REPORT_CONFIRMATION);
	}

	private void playSoundOnce()
	{
		int currentTick = client.getTickCount();
		if (lastPlaybackTick != Integer.MIN_VALUE
			&& currentTick >= lastPlaybackTick
			&& currentTick - lastPlaybackTick <= DUPLICATE_WINDOW_TICKS)
		{
			return;
		}

		lastPlaybackTick = currentTick;
		soundEngine.playClip(Sound.REPORT_PLAYER_1, executor);
	}
}

