class ActionPickerView extends JPanel
{
	private static final String CARD_RESULTS = "RESULTS";
	private static final String CARD_INFO = "INFO";

	private final SoundOverrideService soundOverrideService;
	private final Consumer<String> onPoolSelected;
	private final Runnable onCancel;

	private final IconTextField searchField;
	private final VerticalScrollPane scrollPane;
	private final VerticalScrollPane.ScrollableContainer rowsContainer;
	private final CardLayout cardLayout;
	private final JPanel cardPanel;
	private final PluginErrorPanel infoPanel;

	ActionPickerView(
		SoundOverrideService soundOverrideService,
		Consumer<String> onPoolSelected,
		Runnable onCancel)
	{
		this.soundOverrideService = soundOverrideService;
		this.onPoolSelected = onPoolSelected;
		this.onCancel = onCancel;

		this.searchField = new IconTextField();
		this.scrollPane = new VerticalScrollPane();
		this.rowsContainer = scrollPane.getContainer();
		this.cardLayout = new CardLayout();
		this.cardPanel = new JPanel(cardLayout);
		this.infoPanel = new PluginErrorPanel();

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		configureSearchField();
		buildCardPanel();

		add(buildHeader(), BorderLayout.NORTH);
		add(cardPanel, BorderLayout.CENTER);
	}

	void refresh()
	{
		searchField.setText("");
		SwingUtilities.invokeLater(() -> {
			rebuildRows();
			searchField.requestFocusInWindow();
		});
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(new EmptyBorder(10, 10, 6, 10));

		JLabel titleLabel = new JLabel("New Override");
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);

		JButton closeButton = new JButton();
		closeButton.setIcon(ToolbarIcons.CLOSE);
		closeButton.setRolloverIcon(ToolbarIcons.CLOSE_HOVER);
		closeButton.setToolTipText("Cancel");
		closeButton.setFocusPainted(false);
		SwingUtil.removeButtonDecorations(closeButton);
		closeButton.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		closeButton.setBackground(ColorScheme.DARK_GRAY_COLOR);
		closeButton.addActionListener(event -> {
			if (onCancel != null)
			{
				onCancel.run();
			}
		});

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setOpaque(false);
		titleRow.add(titleLabel, BorderLayout.WEST);
		titleRow.add(closeButton, BorderLayout.EAST);

		JLabel subtitle = new JLabel("Choose which sound to override");
		subtitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		subtitle.setBorder(new EmptyBorder(4, 0, 8, 0));

		header.add(titleRow);
		header.add(subtitle);
		header.add(searchField);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, header.getPreferredSize().height));
		return header;
	}

	private void configureSearchField()
	{
		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setPreferredSize(new Dimension(100, 28));
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchField.addClearListener(this::rebuildRows);
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rebuildRows();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rebuildRows();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rebuildRows();
			}
		});
	}

	private void buildCardPanel()
	{
		cardPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JPanel infoWrapper = new JPanel(new BorderLayout());
		infoWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		infoWrapper.setBorder(new EmptyBorder(20, 8, 20, 8));
		infoPanel.setContent("No matches", "No sounds match your search.");
		infoWrapper.add(infoPanel, BorderLayout.NORTH);

		cardPanel.add(scrollPane, CARD_RESULTS);
		cardPanel.add(infoWrapper, CARD_INFO);
		cardLayout.show(cardPanel, CARD_RESULTS);
	}

	private void rebuildRows()
	{
		SwingUtil.fastRemoveAll(rowsContainer);

		String query = searchField.getText() == null ? "" : searchField.getText().trim().toLowerCase(Locale.ENGLISH);
		int matchCount = 0;
		for (String poolDirectory : SoundPools.allDirectories())
		{
			String displayName = SoundPools.getDisplayName(poolDirectory);
			if (!query.isEmpty()
				&& !displayName.toLowerCase(Locale.ENGLISH).contains(query)
				&& !poolDirectory.toLowerCase(Locale.ENGLISH).contains(query))
			{
				continue;
			}

			boolean alreadyOverridden = !soundOverrideService.getOverrideFileNames(poolDirectory).isEmpty();
			JPanel row = createRow(poolDirectory, displayName, alreadyOverridden);

			JPanel margin = new JPanel(new BorderLayout());
			margin.setBackground(ColorScheme.DARK_GRAY_COLOR);
			margin.setBorder(new EmptyBorder(2, 8, 2, 8));
			margin.add(row, BorderLayout.CENTER);
			margin.setMaximumSize(new Dimension(Integer.MAX_VALUE, margin.getPreferredSize().height));
			rowsContainer.add(margin);
			matchCount++;
		}

		if (matchCount == 0)
		{
			cardLayout.show(cardPanel, CARD_INFO);
		}
		else
		{
			rowsContainer.add(Box.createVerticalGlue());
			cardLayout.show(cardPanel, CARD_RESULTS);
		}

		rowsContainer.revalidate();
		rowsContainer.repaint();
		scrollPane.scrollToTop();
	}

	private JPanel createRow(String poolDirectory, String displayName, boolean alreadyOverridden)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		Color accent = alreadyOverridden ? new Color(95, 175, 95) : ColorScheme.BORDER_COLOR;
		row.setBorder(new CompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			new EmptyBorder(8, 10, 8, 10)
		));

		JLabel nameLabel = new JLabel(displayName);
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setFont(FontManager.getRunescapeFont());

		row.add(nameLabel, BorderLayout.CENTER);

		if (alreadyOverridden)
		{
			JLabel statusLabel = new JLabel("override set");
			statusLabel.setForeground(new Color(95, 175, 95));
			statusLabel.setFont(FontManager.getRunescapeSmallFont());
			row.add(statusLabel, BorderLayout.EAST);
		}

		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setToolTipText(alreadyOverridden
			? "Edit existing override for " + displayName
			: "Create override for " + displayName);

		final Color hoverBackground = ColorScheme.DARK_GRAY_HOVER_COLOR;
		final Color normalBackground = ColorScheme.DARKER_GRAY_COLOR;
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				row.setBackground(hoverBackground);
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				row.setBackground(normalBackground);
			}

			@Override
			public void mouseReleased(MouseEvent event)
			{
				if (event.getButton() == MouseEvent.BUTTON1 && onPoolSelected != null)
				{
					onPoolSelected.accept(poolDirectory);
				}
			}
		});
		return row;
	}
}

package com.github.dappermickie.odablock.ui;

import com.github.dappermickie.odablock.overrides.SoundOverrideService;
import com.google.gson.JsonSyntaxException;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Toolkit;
import java.awt.Window;
import java.awt.datatransfer.DataFlavor;
import java.util.function.Consumer;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;

@Slf4j
class ImportOverridesDialog extends JDialog
{
	private static final Color ERROR_COLOR = new Color(220, 95, 95);
	private static final Color SUCCESS_COLOR = new Color(95, 175, 95);

	private final SoundOverrideService soundOverrideService;
	private final Consumer<String> onImportSucceeded;

	private final JTextArea textArea;
	private final JCheckBox replaceAllToggle;
	private final JLabel statusLabel;
	private final JButton importButton;

	ImportOverridesDialog(
		Window owner,
		SoundOverrideService soundOverrideService,
		Consumer<String> onImportSucceeded)
	{
		super(owner, "Import Odablock Overrides", ModalityType.APPLICATION_MODAL);
		this.soundOverrideService = soundOverrideService;
		this.onImportSucceeded = onImportSucceeded;

		setLayout(new BorderLayout(0, 8));
		getRootPane().setBorder(new EmptyBorder(10, 10, 10, 10));
		getContentPane().setBackground(ColorScheme.DARKER_GRAY_COLOR);

		this.textArea = buildTextArea();
		this.replaceAllToggle = buildReplaceToggle();
		this.statusLabel = new JLabel(" ");
		this.statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		this.statusLabel.setBorder(new EmptyBorder(4, 2, 0, 0));

		this.importButton = new JButton("Import");
		this.importButton.addActionListener(event -> doImport());

		add(buildTopPanel(), BorderLayout.NORTH);
		add(buildCenterPanel(), BorderLayout.CENTER);
		add(buildBottomPanel(), BorderLayout.SOUTH);

		setMinimumSize(new Dimension(360, 280));
		pack();
		setLocationRelativeTo(owner);
	}

	private JPanel buildTopPanel()
	{
		JPanel topPanel = new JPanel(new BorderLayout());
		topPanel.setOpaque(false);
		JLabel pasteLabel = new JLabel("Paste exported overrides JSON:");
		pasteLabel.setForeground(Color.WHITE);
		pasteLabel.setBorder(new EmptyBorder(0, 0, 4, 0));
		topPanel.add(pasteLabel, BorderLayout.NORTH);
		return topPanel;
	}

	private JPanel buildCenterPanel()
	{
		JPanel centerPanel = new JPanel(new BorderLayout(0, 6));
		centerPanel.setOpaque(false);

		JScrollPane textScroll = new JScrollPane(textArea);
		textScroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
		textScroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		textScroll.setPreferredSize(new Dimension(360, 160));

		centerPanel.add(textScroll, BorderLayout.CENTER);
		centerPanel.add(replaceAllToggle, BorderLayout.SOUTH);
		return centerPanel;
	}

	private JPanel buildBottomPanel()
	{
		JPanel bottomPanel = new JPanel(new BorderLayout());
		bottomPanel.setOpaque(false);

		bottomPanel.add(statusLabel, BorderLayout.CENTER);

		JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 5, 0));
		buttonPanel.setOpaque(false);

		JButton cancelButton = new JButton("Cancel");
		cancelButton.addActionListener(event -> dispose());

		buttonPanel.add(importButton);
		buttonPanel.add(cancelButton);

		bottomPanel.add(buttonPanel, BorderLayout.EAST);
		return bottomPanel;
	}

	private JTextArea buildTextArea()
	{
		JTextArea area = new JTextArea(8, 36);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);

		JPopupMenu popup = new JPopupMenu();
		JMenuItem pasteItem = new JMenuItem("Paste");
		pasteItem.addActionListener(event -> {
			try
			{
				Object clipboard = Toolkit.getDefaultToolkit()
					.getSystemClipboard().getData(DataFlavor.stringFlavor);
				if (clipboard instanceof String)
				{
					area.replaceSelection((String) clipboard);
				}
			}
			catch (Exception exception)
			{
				log.debug("Failed to paste from clipboard", exception);
			}
		});
		popup.add(pasteItem);
		area.setComponentPopupMenu(popup);

		return area;
	}

	private JCheckBox buildReplaceToggle()
	{
		JCheckBox toggle = new JCheckBox("Replace all existing overrides");
		toggle.setOpaque(false);
		toggle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		toggle.setToolTipText(
			"<html>If checked, every action's overrides are cleared first.<br>"
				+ "If unchecked, only actions present in the JSON are replaced.</html>");
		return toggle;
	}

	private void doImport()
	{
		String json = textArea.getText() == null ? "" : textArea.getText().trim();
		if (json.isEmpty())
		{
			showError("Paste an exported overrides JSON first.");
			return;
		}

		try
		{
			SoundOverrideService.ImportResult result = replaceAllToggle.isSelected()
				? soundOverrideService.replaceAllOverridesFromJson(json)
				: soundOverrideService.importOverridesFromJson(json);

			SwingUtilities.invokeLater(() -> {
				if (onImportSucceeded != null)
				{
					onImportSucceeded.accept(buildSuccessSummary(result));
				}
				dispose();
			});
		}
		catch (JsonSyntaxException exception)
		{
			log.debug("Invalid overrides JSON pasted", exception);
			showError("Invalid JSON. Make sure you pasted an exported overrides payload.");
		}
		catch (Exception exception)
		{
			log.warn("Failed to import overrides", exception);
			showError("Import failed: " + exception.getMessage());
		}
	}

	private void showError(String message)
	{
		statusLabel.setForeground(ERROR_COLOR);
		statusLabel.setText(message);
	}

	private String buildSuccessSummary(SoundOverrideService.ImportResult result)
	{
		StringBuilder builder = new StringBuilder();
		int imported = result.getImportedActions();
		if (imported == 0)
		{
			builder.append("No matching actions to import.");
		}
		else if (imported == 1)
		{
			builder.append("Imported 1 action override.");
		}
		else
		{
			builder.append("Imported ").append(imported).append(" action overrides.");
		}
		if (result.getSkippedActions() > 0)
		{
			builder.append(" Skipped ").append(result.getSkippedActions()).append(" unknown action(s).");
		}
		return builder.toString();
	}
}

package com.github.dappermickie.odablock.ui;

import com.github.dappermickie.odablock.overrides.SoundOverrideOption;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
